+const IDENTIFIERS = "[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*";
+const VERSION_RE = new RegExp(`^v?([0-9]+)\\.([0-9]+)\\.([0-9]+)(?:-(${IDENTIFIERS}))?(?:\\+${IDENTIFIERS})?$`);
+
 /** Parse a version string. See README.md for the accepted syntax. */
 export function parseVersion(text: string): Version {
-  throw new Error("not implemented");
+  const match = VERSION_RE.exec(text.trim());
+  if (!match) {
+    throw new Error(`invalid version: ${JSON.stringify(text)}`);
+  }
+  return {
+    major: Number(match[1]),
+    minor: Number(match[2]),
+    patch: Number(match[3]),
+    prerelease: match[4] === undefined ? [] : match[4].split("."),
+  };
+}
+
+function sign(n: number | bigint): -1 | 0 | 1 {
+  return n < 0 ? -1 : n > 0 ? 1 : 0;
+}
+
+const isNumeric = (id: string): boolean => /^[0-9]+$/.test(id);
+
+function compareIdentifiers(a: string, b: string): -1 | 0 | 1 {
+  const aNum = isNumeric(a);
+  const bNum = isNumeric(b);
+  if (aNum && bNum) return sign(BigInt(a) - BigInt(b));
+  if (aNum) return -1;
+  if (bNum) return 1;
+  return a < b ? -1 : a > b ? 1 : 0;
+}
+
+function compareParsed(a: Version, b: Version): -1 | 0 | 1 {
+  const core = sign(a.major - b.major) || sign(a.minor - b.minor) || sign(a.patch - b.patch);
+  if (core !== 0) return core;
+
+  if (a.prerelease.length === 0 || b.prerelease.length === 0) {
+    return sign(b.prerelease.length - a.prerelease.length);
+  }
+
